shellCommands.command:
cd /home/sandbox/workspace; rm -rf dist; cat > /tmp/i18n-check.mjs <<'EOF'
import { I18N } from '/home/sandbox/workspace/node_modules/@gravity-ui/i18n/build/esm/index.js';
const en = { app: { title: 'Gravity UI demo', pageStatus: 'Page {{page}} of {{pages}}', savedHint: 'saved' } };
const ru = { app: { title: 'Демо Gravity UI', pageStatus: 'Страница {{page}} из {{pages}}', savedHint: 'сохраняется' } };
const i18n = new I18N({ lang: 'en', fallbackLang: 'en' });
i18n.registerKeysets('en', en.app ? en : en);
i18n.registerKeysets('ru', ru);
const t = i18n.keyset('app');
console.log(t('title'), '|', t('pageStatus', { page: 2, pages: 10 }));
i18n.setLang('ru');
console.log(t('title'), '|', t('pageStatus', { page: 2, pages: 10 }));
i18n.setLang('de'); // unknown lang -> fallback
console.log(t('title'));
EOF
node /tmp/i18n-check.mjs; rm -f /tmp/i18n-check.mjs

mkdir -p /tmp/i18n-check && cat > /tmp/i18n-check/check.cjs <<'EOF'
const { I18N } = require('/home/sandbox/workspace/node_modules/@gravity-ui/i18n/build/cjs/index.js');
const en = { app: { title: 'Gravity UI demo', pageStatus: 'Page {{page}} of {{pages}}' } };
const ru = { app: { title: 'Демо Gravity UI', pageStatus: 'Страница {{page}} из {{pages}}' } };
const i18n = new I18N({ lang: 'en', fallbackLang: 'en' });
i18n.registerKeysets('en', en);
i18n.registerKeysets('ru', ru);
const t = i18n.keyset('app');
console.log('en:', t('title'), '|', t('pageStatus', { page: 2, pages: 10 }));
i18n.setLang('ru');
console.log('ru:', t('title'), '|', t('pageStatus', { page: 2, pages: 10 }));
i18n.setLang('de');
console.log('de->fallback:', t('title'));
EOF
node /tmp/i18n-check/check.cjs; rm -rf /tmp/i18n-check
